const body = $json.body;
const raw = body.raw;
const source = body.source;

const out = {
  alert_id: body.alert_id,
  timestamp: null,
  alert_type: null,
  source: source,
  severity: 'medium',
  observables: { ip: [], hash: [], domain: [], url: [], user: [], host: [] },
  extra: {},
  raw: raw,
  parse_error: null
};

try {
  if (source === 'syslog') {
    out.alert_type = 'suspicious_login';
    const months = {Jan:'01',Feb:'02',Mar:'03',Apr:'04',May:'05',Jun:'06',
                    Jul:'07',Aug:'08',Sep:'09',Oct:'10',Nov:'11',Dec:'12'};
    const m = raw.match(/^(\w{3})\s+(\d+)\s([\d:]+)\s(\S+)/);
    if (m) {
      // syslog-da il yoxdur, dataset 2026-dır
      out.timestamp = `2026-${months[m[1]]}-${m[2].padStart(2, '0')}T${m[3]}Z`;
      out.observables.host.push(m[4]);
    }
    const u = raw.match(/for (?:invalid user )?(\S+) from (\d+\.\d+\.\d+\.\d+)/);
    if (u) { out.observables.user.push(u[1]); out.observables.ip.push(u[2]); }
    const a = raw.match(/attempts=(\d+)/);
    if (a) out.extra.attempts = parseInt(a[1], 10);

  } else if (source === 'edr') {
    out.alert_type = 'malicious_hash';
    const j = JSON.parse(raw);
    out.timestamp = j.timestamp || null;
    if (j.host) out.observables.host.push(j.host);
    if (j.sha256) out.observables.hash.push(j.sha256);
    if (j.severity) out.severity = j.severity;

  } else if (source === 'proxy') {
    out.alert_type = 'suspicious_url';
    const kv = {};
    for (const m of raw.matchAll(/(\w+)=("[^"]*"|\S+)/g)) {
      kv[m[1]] = m[2].replace(/^"|"$/g, '');
    }
    out.timestamp = kv.ts || null;
    if (kv.src) out.observables.ip.push(kv.src);
    if (kv.domain) out.observables.domain.push(kv.domain);
    if (kv.url) out.observables.url.push(kv.url);

  } else {
    out.parse_error = 'namelum source: ' + source;
  }
} catch (e) {
  out.parse_error = e.name + ': ' + e.message;
}

return { json: out };
